/* ECCC / CMC RDPS astronomy forecasts via MSC GeoMet WMS. No interpolation. */
(function(root){
'use strict';
const endpoint='https://geo.weather.gc.ca/geomet/';
const layers={seeing:'RDPS_10km_SeeingIndex',transparency:'RDPS_10km_SkyTransparencyIndex'};
const cache=new Map(),metadata=new Map();let active=0;const queue=[];
function limit(fn){return new Promise((resolve,reject)=>{queue.push({fn,resolve,reject});drain()})}
function drain(){while(active<2&&queue.length){const job=queue.shift();active++;Promise.resolve().then(job.fn).then(job.resolve,job.reject).finally(()=>{active--;drain()})}}
async function fetchText(params){return limit(async()=>{const response=await fetch(endpoint+'?'+new URLSearchParams({SERVICE:'WMS',VERSION:'1.3.0',...params}),{signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error('CMC service unavailable');return response.text()})}
async function capabilities(layer){let entry=metadata.get(layer);if(entry&&Date.now()-entry.created<1800000)return entry.promise;const promise=(async()=>{const xml=new DOMParser().parseFromString(await fetchText({REQUEST:'GetCapabilities',LAYERS:layer}),'application/xml');if(xml.querySelector('parsererror'))throw Error('Invalid CMC metadata');const node=Array.from(xml.getElementsByTagNameNS('*','Layer')).find(n=>Array.from(n.children).some(c=>c.localName==='Name'&&c.textContent===layer));if(!node)throw Error('CMC layer unavailable');const dimensions=Array.from(node.children).filter(c=>c.localName==='Dimension');const time=dimensions.find(c=>c.getAttribute('name')==='time'),ref=dimensions.find(c=>c.getAttribute('name')==='reference_time')?.getAttribute('default');if(!time||!ref)throw Error('CMC forecast times unavailable');const [start,end,step]=time.textContent.trim().split('/');const match=/^PT(\d+)H$/.exec(step||'');if(!match||!Number.isFinite(Date.parse(start))||!Number.isFinite(Date.parse(end))||!Number.isFinite(Date.parse(ref)))throw Error('Unsupported CMC forecast times');return {start:Date.parse(start),end:Date.parse(end),step:Number(match[1])*3600000,reference:ref}})();metadata.set(layer,{promise,created:Date.now()});promise.catch(()=>metadata.delete(layer));return promise}
function parsePoint(data,layer,time,reference){if(data?.layer!==layer||!Array.isArray(data.features)||data.features.length!==1)return null;const f=data.features[0],p=f.properties;if(!p||typeof p.value!=='number'||(!Number.isInteger(p.value)||p.value<0||p.value>5)||Date.parse(p.time)!==Date.parse(time)||Date.parse(p.dim_reference_time)!==Date.parse(reference))return null;return {value:p.value,label:typeof p.class==='string'?p.class:null,time:p.time,reference:p.dim_reference_time,coordinates:f.geometry?.coordinates||null}}
async function point(field,lat,lon,date){const layer=layers[field],meta=await capabilities(layer),t=+date;if(t<meta.start||t>meta.end||(t-meta.start)%meta.step!==0)return {data:null,reason:'No CMC forecast for this exact hour.'};const key=[layer,lat,lon,t,meta.reference].join('|');if(cache.has(key))return cache.get(key);const promise=(async()=>{const time=new Date(t).toISOString().replace('.000Z','Z');const south=Math.max(-90,lat-.01),north=Math.min(90,lat+.01),west=Math.max(-180,lon-.01),east=Math.min(180,lon+.01);const raw=await fetchText({REQUEST:'GetFeatureInfo',LAYERS:layer,QUERY_LAYERS:layer,CRS:'EPSG:4326',BBOX:[south,west,north,east].join(','),WIDTH:'11',HEIGHT:'11',I:'5',J:'5',FORMAT:'image/png',INFO_FORMAT:'application/json',TIME:time,DIM_REFERENCE_TIME:meta.reference});let parsed;try{parsed=JSON.parse(raw)}catch{throw Error('CMC response unavailable')}const data=parsePoint(parsed,layer,time,meta.reference);return {data,reason:data?null:'No valid CMC data at this location and hour.'}})();cache.set(key,promise);promise.catch(()=>cache.delete(key));if(cache.size>500)cache.delete(cache.keys().next().value);return promise}
root.CMC={point,parsePoint};
})(typeof window!=='undefined'?window:globalThis);
